class Reassembler:
    def __init__(self):
        self._buf = bytearray()
        self._state = 'SYNC'  # SYNC, LEN, PAYLOAD, CHECK
        self._len = 0
        self._payload = bytearray()
        self._sync_count = 0

    def feed(self, chunk: bytes) -> list[bytes]:
        results = []
        self._buf.extend(chunk)
        i = 0
        n = len(self._buf)

        while i < n:
            if self._state == 'SYNC':
                # Look for 0xAA 0x55
                if self._buf[i] == 0xAA:
                    if i + 1 < n:
                        if self._buf[i + 1] == 0x55:
                            self._state = 'LEN'
                            self._len = 0
                            self._payload = bytearray()
                            i += 2
                            continue
                        else:
                            i += 1
                            continue
                    else:
                        # Only 0xAA at end of buffer, wait for more
                        break
                else:
                    i += 1
            elif self._state == 'LEN':
                if i + 1 < n:
                    self._len = self._buf[i] | (self._buf[i + 1] << 8)
                    i += 2
                    if self._len > 4096:
                        # Invalid length, discard and resync
                        self._state = 'SYNC'
                        continue
                    else:
                        self._state = 'PAYLOAD'
                        self._payload = bytearray()
                        continue
                else:
                    # Only one byte of length available
                    self._len = self._buf[i]
                    i += 1
                    self._state = 'LEN_HI'
                    continue
            elif self._state == 'LEN_HI':
                self._len |= (self._buf[i] << 8)
                i += 1
                if self._len > 4096:
                    self._state = 'SYNC'
                    continue
                else:
                    self._state = 'PAYLOAD'
                    self._payload = bytearray()
                    continue
            elif self._state == 'PAYLOAD':
                remaining = self._len - len(self._payload)
                if remaining <= 0:
                    self._state = 'CHECK'
                    continue
                take = min(remaining, n - i)
                self._payload.extend(self._buf[i:i + take])
                i += take
                if len(self._payload) == self._len:
                    self._state = 'CHECK'
                continue
            elif self._state == 'CHECK':
                expected = 0
                for b in self._payload:
                    expected ^= b
                if self._buf[i] == expected:
                    results.append(bytes(self._payload))
                # Whether valid or not, resync
                self._state = 'SYNC'
                i += 1
                continue
            else:
                i += 1

        self._buf = self._buf[i:]
        return results
